function Academics({
  setPage,
  selectedClasses,
  setSelectedClasses,
  }) {
    const [major, setMajor] = useState("");
    const [plannedMajor, setPlannedMajor] = useState("");
    const [classSearch, setClassSearch] = useState("");

  function addClass(course) {
    const alreadySelected = selectedClasses.some(
      (selectedCourse) =>
        selectedCourse.code === course.code
    );

    if (alreadySelected) {
      setClassSearch("");
      return;
    }

    setSelectedClasses((previousClasses) => [
      ...previousClasses,
      course,
    ]);

    setClassSearch("");
  }

  function removeClass(courseCode) {
    setSelectedClasses((previousClasses) =>
      previousClasses.filter(
        (course) => course.code !== courseCode
      )
    );
  }

  const cleanedSearch = classSearch.trim().toLowerCase();

  const filteredCourses = cleanedSearch
    ? sjsuCourses.filter((course) => {
        const courseCode = course.code.toLowerCase();
        const courseTitle = course.title.toLowerCase();

        return (
          courseCode.includes(cleanedSearch) ||
          courseTitle.includes(cleanedSearch)
        );
      })
    : [];

  return (
    <div className="academics-container">
      <img
        className="academics-image"
        src={academicsPage}
        alt="Academics Page"
      />

      <input
        type="text"
        className="major-search-input"
        list="sjsu-majors"
        value={major}
        onChange={(event) => setMajor(event.target.value)}
        placeholder="Search for your current major"
        autoComplete="off"
      />

      <input
        type="text"
        className="switch-major-search-input"
        list="sjsu-majors"
        value={plannedMajor}
        onChange={(event) =>
          setPlannedMajor(event.target.value)
        }
        placeholder="Search for a major you may switch to"
        autoComplete="off"
      />

      <datalist id="sjsu-majors">
        {sjsuMajors.map((majorName) => (
          <option
            key={majorName}
            value={majorName}
          />
        ))}
      </datalist>

      <div className="class-selector">
        <input
          type="text"
          className="class-search-input"
          value={classSearch}
          onChange={(event) =>
            setClassSearch(event.target.value)
          }
          placeholder="Search by course code or title"
          autoComplete="off"
        />

        {cleanedSearch && (
          <div className="class-search-results">
            {filteredCourses.length > 0 ? (
              filteredCourses.slice(0, 8).map((course) => {
                const isSelected = selectedClasses.some(
                  (selectedCourse) =>
                    selectedCourse.code === course.code
                );

                return (
                  <button
                    type="button"
                    className="class-result-button"
                    key={`${course.code}-${course.title}`}
                    onClick={() => addClass(course)}
                    disabled={isSelected}
                  >
                    <strong>{course.code}</strong>

                    <span>{course.title}</span>

                    {isSelected && (
                      <span className="already-selected-text">
                        Already selected
                      </span>
                    )}
                  </button>
                );
              })
            ) : (
              <p className="no-class-results">
                No matching classes found
              </p>
            )}
          </div>
        )}

        <div className="selected-classes">
          {selectedClasses.map((course) => (
            <div
              className="selected-class-tag"
              key={`${course.code}-${course.title}`}
            >
              <span>
                {course.code} — {course.title}
              </span>

              <button
                type="button"
                className="remove-class-button"
                onClick={() => removeClass(course.code)}
                aria-label={`Remove ${course.code}`}
              >
                ×
              </button>
            </div>
          ))}
        </div>
      </div>

      <button
        type="button"
        className="academics-back-button"
        onClick={() => setPage("basic")}
      >
        Back
      </button>

      <button
        type="button"
        className="academics-next-button"
        onClick={() => setPage("interests")}
      >
        Next
      </button>
    </div>
  );
}

export default Academics;